using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

// ── Tool implementations ────────────────────────────────────────────────

/// <summary>Provides web-search and note-taking tools the agent can invoke.</summary>
public static class ResearchTools
{
    private static readonly List<string> s_notes = [];
    private static readonly HttpClient s_http = new();

    /// <summary>Search the web for the given query and return a summary of results.</summary>
    [Description("Search the web for a query and return result snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍  Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var doc = await s_http.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            var abstractText = doc.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"Summary: {abstractText}");

            if (doc.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                        results.Add($"- {text.GetString()}");
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No instant-answer results for \"{query}\". Try rephrasing.";
        }
        catch (Exception ex)
        {
            return $"Search failed ({ex.Message}). Try a different query.";
        }
    }

    /// <summary>Save a research note for later summarization.</summary>
    [Description("Save a research note. Use this to record important findings.")]
    public static string SaveNote(
        [Description("The note content to save")] string note)
    {
        s_notes.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝  Note #{s_notes.Count} saved ({note.Length} chars)");
        Console.ResetColor();
        return $"Note #{s_notes.Count} saved.";
    }

    /// <summary>Retrieve all saved research notes.</summary>
    [Description("Retrieve all research notes saved so far.")]
    public static string GetNotes()
    {
        if (s_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", s_notes.Select((n, i) => $"[{i + 1}] {n}"));
    }
}

// ── Agent loop ──────────────────────────────────────────────────────────

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║      🤖  AI Research Agent           ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.ForegroundColor = ConsoleColor.Red;
    Console.WriteLine("Set the OPENAI_API_KEY environment variable to run this agent.");
    Console.ResetColor();
    return;
}

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = AIFunctionFactory.Create(ResearchTools.SearchWeb, ResearchTools.SaveNote, ResearchTools.GetNotes);

var chatOptions = new ChatOptions
{
    Tools = [.. tools],
    ToolMode = ChatToolMode.Auto
};

var systemPrompt = """
    You are a research agent. Given a topic, you:
    1. Search the web multiple times with varied queries to gather information.
    2. Save important findings as notes using the SaveNote tool.
    3. After gathering enough information, retrieve your notes and produce a
       well-structured summary with key points and references.
    Be thorough — perform at least 2-3 searches before summarizing.
    """;

var history = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt)
};

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

history.Add(new ChatMessage(ChatRole.User,
    $"Research the following topic and provide a comprehensive summary:\n\n{topic}"));

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.DarkGray;
Console.WriteLine("Agent is researching… (tool calls will appear below)");
Console.ResetColor();
Console.WriteLine();

const int maxIterations = 10;
for (var i = 0; i < maxIterations; i++)
{
    var response = await chatClient.GetResponseAsync(history, chatOptions);

    // Append all response messages to history
    foreach (var msg in response.Messages)
        history.Add(msg);

    // Check if the model is done (no more tool calls)
    bool hasToolCalls = response.Messages
        .Any(m => m.Contents.OfType<FunctionCallContent>().Any());

    if (!hasToolCalls)
    {
        // Final answer
        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("═══════════════  Research Summary  ═══════════════");
        Console.ResetColor();
        Console.WriteLine();

        var finalText = response.Messages
            .SelectMany(m => m.Contents.OfType<TextContent>())
            .LastOrDefault()?.Text ?? "(no summary produced)";
        Console.WriteLine(finalText);

        Console.WriteLine();
        Console.ForegroundColor = ConsoleColor.DarkGray;
        Console.WriteLine($"Completed in {i + 1} iteration(s).");
        Console.ResetColor();
        break;
    }
}

